from datetime import datetime

def to_dt(s):
    if s is None:
        return None
    try:
        return datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        try:
            return datetime.strptime(s,'%Y-%m-%dT%H:%M:%S')
        except Exception:
            return None

sorted_by_created = sorted(brandon_requests, key=lambda r: (to_dt(r.get('created_at')) or datetime.min), reverse=True)
sorted_by_approved = sorted(brandon_requests, key=lambda r: (to_dt(r.get('approved_at')) or datetime.min), reverse=True)
print('Top by created_at:')
for r in sorted_by_created[:3]:
    print(r.get('payment_request_id'), r.get('amount'), r.get('created_at'), r.get('approved_at'))

print('Top by approved_at:')
for r in sorted_by_approved[:3]:
    print(r.get('payment_request_id'), r.get('amount'), r.get('created_at'), r.get('approved_at'))

latest_created = sorted_by_created[0]
latest_approved = sorted_by_approved[0]
print('latest_created_id', latest_created.get('payment_request_id'))
print('latest_approved_id', latest_approved.get('payment_request_id'))

